CREATE POLICY pilot_photo_staff_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='whispers-private' AND EXISTS(SELECT 1 FROM public.whispers_reports r WHERE r.id::text=split_part(name,'/',1) AND public.whispers_access(r.workspace,'reviewer') AND r.revoked_at IS NULL AND r.expires_at>now()));
CREATE FUNCTION public.whispers_expire_private() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN
WITH due AS (SELECT id FROM public.whispers_reports WHERE expires_at<=now() AND revoked_at IS NULL), removed_records AS (DELETE FROM public.whispers_records WHERE report_id IN (SELECT id FROM due)), removed_packets AS (DELETE FROM public.whispers_expert_requests WHERE report_ids && ARRAY(SELECT id FROM due)) UPDATE public.whispers_reports SET body=jsonb_build_object('expired',true,'fictional',true),revoked_at=now() WHERE id IN(SELECT id FROM due); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.whispers_expire_private() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.whispers_expire_private() TO service_role;
COMMENT ON FUNCTION public.whispers_expire_private() IS 'Expires private testimony and derived private records; storage object cleanup is handled separately. Backups and published summaries have separate operator policies.';
CREATE FUNCTION public.whispers_photo_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.kind='photo' THEN PERFORM 1 FROM public.whispers_reports WHERE id=NEW.report_id FOR UPDATE; IF (SELECT count(*) FROM public.whispers_records WHERE report_id=NEW.report_id AND kind='photo')>=3 THEN RAISE EXCEPTION 'At most three photos'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER whispers_photo_limit BEFORE INSERT ON public.whispers_records FOR EACH ROW EXECUTE FUNCTION public.whispers_photo_limit();